def test_axios_next_story_preserves_short_quote_attribution():
    canonical_url = (
        "https://www.axios.com/2018/01/26/"
        "trump-nyt-mueller-fired-fake-news"
    )
    story = {
        "headline": "Trump dismisses NYT after Mueller scoop",
        "permalink": canonical_url,
        "published_date": "2018-01-26T09:47:07Z",
        "wordcount": 35,
        "blocks": {
            "blocks": [
                {
                    "type": "styled-quote",
                    "text": (
                        "Fake news. Fake news. Typical New York Times. "
                        "Fake stories."
                    ),
                    "data": {},
                },
                {
                    "type": "quote-attribution",
                    "text": (
                        "Trump on the NYT scoop that he tried to fire Robert "
                        "Mueller last year, stopping only because White House "
                        "Counsel Don McGahn threatened to resign."
                    ),
                    "data": {},
                },
            ],
            "entityMap": [],
        },
        "bodyHtml": {
            "beforeKeepReading": (
                "<blockquote>Fake news. Fake news. Typical New York Times. "
                "Fake stories.</blockquote>"
                "<cite>Trump on the NYT scoop that he tried to fire Robert "
                "Mueller last year, stopping only because White House Counsel "
                "Don McGahn threatened to resign.</cite>"
            ),
            "afterKeepReading": "",
        },
    }
    next_data = {"props": {"pageProps": {"data": {"story": story}}}}
    html = (
        "<html><body><script id='__NEXT_DATA__' type='application/json'>"
        + json.dumps(next_data)
        + "</script></body></html>"
    ).encode()

    result = parse_article(
        html,
        publisher="axios",
        canonical_url=canonical_url,
        raw_capture=raw_capture("axios", canonical_url),
    )

    assert result.quality.status.value == "complete"
    assert [block.type.value for block in result.blocks] == [
        "quote",
        "paragraph",
    ]
    assert "Trump on the NYT scoop" in result.plain_text
    assert 'data-jojo-role="quote-attribution"' in result.body_html
    assert result.extraction.parser_version == "axios-parser/0.1.33"


def test_axios_next_story_selects_canonical_deep_dive_chapter():
    canonical_url = "https://www.axios.com/2021/02/06/inheriting-inequality"
    first_story = {
        "headline": "1. Biden's economic luck",
        "permalink": "https://www.axios.com/2021/02/06/biden-economy-recovery",
        "published_date": "2021-02-06T12:00:00Z",
        "blocks": {
            "blocks": [
                {
                    "type": "unstyled",
                    "text": "The first chapter discusses the broad economy.",
                    "data": {},
                }
            ],
            "entityMap": [],
        },
        "bodyHtml": {
            "beforeKeepReading": (
                "<p>The first chapter discusses the broad economy.</p>"
            ),
            "afterKeepReading": "",
        },
    }
    target_story = {
        "headline": "5. Inheriting inequality",
        "permalink": canonical_url,
        "published_date": "2021-02-06T12:00:00Z",
        "blocks": {
            "blocks": [
                {
                    "type": "unstyled",
                    "text": (
                        "The target chapter explains how inherited wealth "
                        "shapes household opportunity across generations."
                    ),
                    "data": {},
                }
            ],
            "entityMap": [],
        },
        "bodyHtml": {
            "beforeKeepReading": (
                "<p>The target chapter explains how inherited wealth shapes "
                "household opportunity across generations.</p>"
            ),
            "afterKeepReading": "",
        },
    }
    next_data = {
        "props": {
            "pageProps": {
                "deepDive": [first_story, target_story],
                "story": target_story,
            }
        }
    }
    html = (
        "<html><body><script id='__NEXT_DATA__' type='application/json'>"
        + json.dumps(next_data)
        + "</script></body></html>"
    ).encode()

    result = parse_article(
        html,
        publisher="axios",
        canonical_url=canonical_url,
        raw_capture=raw_capture("axios", canonical_url),
    )

    assert result.headline == "5. Inheriting inequality"
    assert "inherited wealth" in result.plain_text
    assert "broad economy" not in result.plain_text
    assert result.extraction.parser_version == "axios-parser/0.1.33"


