def test_nyt_parser_recovers_legacy_standalone_slideshow_json():
    slides = []
    for index in range(3):
        slides.append(
            {
                "slide_url": f"historical-slide-{index}",
                "caption": {
                    "full": (
                        f"<p>Historical photograph {index} caption.</p>"
                    )
                },
                "credit": f"Archive Photographer {index}",
                "image_crops": {
                    "thumb": {
                        "width": 190,
                        "height": 126,
                        "url": (
                            "https://static01.nyt.com/images/"
                            f"historical-{index}/"
                            f"historical-{index}-thumb.jpg"
                        ),
                    },
                    "jumbo": {
                        "width": 1024,
                        "height": 683,
                        "url": (
                            "https://static01.nyt.com/images/"
                            f"historical-{index}/"
                            f"historical-{index}-jumbo.jpg"
                        ),
                    },
                },
            }
        )
    payload = json.dumps(
        {
            "headline": "Street Style: London",
            "summary": "Fashion week on the streets of London.",
            "imageslideshow": {"slides": slides},
        }
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="Street Style: London">
      <meta property="og:image"
            content="https://static01.nyt.com/images/historical-0/historical-0-facebookJumbo.jpg">
      <meta property="article:published_time"
            content="2015-09-21T00:00:00Z">
    </head><body>
      <script type="application/json">{payload}</script>
    </body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2015/09/21/fashion/"
            "street-style-london.html"
        ),
    )

    assert result.content_type.value == "gallery"
    assert result.quality.status.value == "complete"
    assert result.quality.images_selected == 3
    assert [image.original_url for image in result.images] == [
        (
            "https://static01.nyt.com/images/historical-0/"
            "historical-0-facebookJumbo.jpg"
        ),
        (
            "https://static01.nyt.com/images/historical-1/"
            "historical-1-jumbo.jpg"
        ),
        (
            "https://static01.nyt.com/images/historical-2/"
            "historical-2-jumbo.jpg"
        ),
    ]
    assert result.images[0].caption == "Historical photograph 0 caption."
    assert result.images[0].credit == "Credit: Archive Photographer 0"


def test_nyt_parser_keeps_article_body_over_embedded_legacy_slideshow():
    slides = [
        {
            "slide_url": f"shared-slide-{index}",
            "caption": {"full": f"<p>Shared event caption {index}.</p>"},
            "image_crops": {
                "jumbo": {
                    "width": 1024,
                    "height": 683,
                    "url": f"https://static01.nyt.com/shared-{index}.jpg",
                }
            },
        }
        for index in range(3)
    ]
    payload = json.dumps({"imageslideshow": {"slides": slides}})
    prose = (
        "The Samoyeds waited beside the judging ring while their handlers "
        "described the breed's history and temperament. " * 5
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="A Fluffy White Dark Horse">
      <meta property="article:published_time"
            content="2016-02-17T00:00:00Z">
    </head><body>
      <article class="story theme-main">
        <div class="story-body">
          <p class="story-body-text story-content"
             itemprop="articleBody">{prose}</p>
          <figure class="media slideshow promo embedded">
            <script type="application/json">{payload}</script>
          </figure>
          <p class="story-body-text story-content"
             itemprop="articleBody">The judge selected a finalist.</p>
        </div>
      </article>
    </body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2016/02/17/sports/"
            "westminster-kennel-club-dog-show-samoyeds.html"
        ),
    )

    assert result.quality.status == ArticleStatus.COMPLETE
    assert "The Samoyeds waited" in result.plain_text
    assert "The judge selected" in result.plain_text
    assert "Shared event caption" not in result.plain_text
    assert result.extraction.parser_version == "nyt-parser/0.8.158"


