def test_ft_parser_removes_amp_em_dash_separator_paragraphs():
    reporting = " ".join(["Financial Times reporting sentence."] * 30)
    result = parse_article(
        f"""
        <html><head>
          <meta property="og:title" content="A historical FT report">
          <meta property="article:published_time"
                content="2016-06-12T00:00:00Z">
        </head><body><article><div class="article-body">
          <p>{reporting}</p>
          <p>————————-</p>
          <p>——————–</p>
          <p>……………………………………………………………..</p>
          <p>Further editorial reporting remains after the visual rule.</p>
        </div></article></body></html>
        """.encode(),
        publisher="ft",
        canonical_url="https://www.ft.com/content/amp-rule-report",
    )

    assert result.quality.status == ArticleStatus.COMPLETE
    assert result.extraction.parser_version == "ft-parser/0.8.69"
    assert "————————-" not in result.plain_text
    assert "——————–" not in result.plain_text
    assert "…………………………………………………………….." not in result.plain_text
    assert all(
        block.text
        not in {
            "————————-",
            "——————–",
            "……………………………………………………………..",
        }
        for block in result.blocks
    )


