def test_ft_parser_removes_structurally_proven_coronavirus_cards():
    reporting = " ".join(["Financial Times reporting sentence."] * 30)
    result = parse_article(
        f"""
        <html><head>
          <meta property="og:title" content="A complete FT report">
          <meta property="article:published_time"
                content="2020-05-01T00:00:00Z">
        </head><body><article><div class="article-body">
          <p>{reporting}</p>
          <experimental><div class="n-content-layout">
            <div class="n-content-layout__container">
              <h2>Latest coronavirus news</h2>
              <div class="n-content-layout__slot">
                <figure class="n-content-image p402_hide">
                  <img src="https://d1e00ek4ebabms.cloudfront.net/promo.jpg">
                </figure>
                <p>Follow FT's live coverage and analysis of the global
                   pandemic and the rapidly evolving economic crisis
                   <a href="/coronavirus">here</a>.</p>
              </div>
            </div>
          </div></experimental>
          <div class="n-content-layout">
            <div class="n-content-layout__slot">
              <h3>Read more about the impact of coronavirus</h3>
              <ul>
                <li><a href="/content/related-one">Related one</a></li>
                <li><a href="/content/related-two">Related two</a></li>
              </ul>
              <p><a href="/myft">Subscribers can use myFT to follow the
                 latest coronavirus coverage</a></p>
            </div>
          </div>
          <div class="n-content-layout">
            <div class="n-content-layout__container">
              <h2>Editor’s note</h2>
              <div class="n-content-layout__slot"><p>The Financial Times is
                making key coronavirus coverage free to read to help everyone
                stay informed. <a href="/coronavirus">Find the latest here</a>.
              </p></div>
            </div>
          </div>
          <h3>Read more about the impact of coronavirus</h3>
          <p><a href="/content/related-three">A related report</a></p>
          <div class="n-content-video"><a href="/video/related">Video:
            markets woke up to the threat</a></div>
          <p>How markets woke up to the threat</p>
          <p><a href="/myft">Subscribers can use myFT to follow the latest
             coronavirus coverage</a></p>
          <p><a href="https://twitter.com/reporter">Follow the reporter</a>
             for future reporting.</p>
          <h2>Don’t miss</h2>
          <p>This is a genuine section in the Trade Secrets newsletter.</p>
          <h2>Smart reads</h2>
          <p>This is a genuine section in the Due Diligence newsletter.</p>
          <p>We’re offering a free 30-day trial to Coronavirus Business
             Update, our level-headed briefing on how the epidemic is
             affecting markets and global business. Please forward this
             newsletter to friends. They can sign up here.</p>
          <h2>Editor’s note</h2>
          <p>A substantive correction to the reported figure remains.</p>
        </div></article></body></html>
        """.encode(),
        publisher="ft",
        canonical_url="https://www.ft.com/content/coronavirus-cards",
    )

    assert result.quality.status == ArticleStatus.COMPLETE
    assert "Latest coronavirus news" not in result.plain_text
    assert "Read more about the impact" not in result.plain_text
    assert "making key coronavirus coverage free" not in result.plain_text
    assert "A related report" not in result.plain_text
    assert "markets woke up to the threat" not in result.plain_text
    assert "Follow the reporter" in result.plain_text
    assert "Don’t miss" in result.plain_text
    assert "Smart reads" in result.plain_text
    assert "free 30-day trial" not in result.plain_text
    assert "substantive correction" in result.plain_text
    assert result.quality.images_selected == 0


def test_ft_parser_removes_coronavirus_promos_from_json_ld_article_body():
    reporting = " ".join(["Financial Times reporting sentence."] * 24)
    final_reporting = (
        "Officials then published the final decision and explained how the "
        "new policy would affect companies and workers."
    )
    article_body = "\n\n".join(
        [
            reporting,
            (
                "CORONAVIRUS BUSINESS UPDATE\n"
                "[http://com.ft.imagepublish.upp-prod-eu.s3.amazonaws.com/"
                "coronavirus-promo]\nHow is coronavirus taking its toll on "
                "markets and business? Stay briefed with our coronavirus "
                "newsletter."
            ),
            "Sign up here",
            final_reporting,
            (
                "Latest coronavirus news\nFollow FT's live coverage and "
                "analysis of the global pandemic and economic crisis."
            ),
            (
                "Read more about the impact of coronavirus\nThe latest "
                "figures as the outbreak spreads\nHow markets woke up to "
                "the threat"
            ),
            "Editor’s note",
            (
                "The Financial Times is making key coronavirus coverage free "
                "to read to help everyone stay informed."
            ),
            "Editor’s note",
            "A substantive correction to the reported figure remains.",
        ]
    )
    payload = json.dumps(
        {
            "@context": "https://schema.org",
            "@type": "NewsArticle",
            "headline": "A complete structured FT report",
            "datePublished": "2020-05-01T00:00:00Z",
            "articleBody": article_body,
        }
    )
    result = parse_article(
        f"<html><head><script type='application/ld+json'>{payload}</script>"
        "</head><body></body></html>".encode(),
        publisher="ft",
        canonical_url="https://www.ft.com/content/structured-coronavirus-cards",
    )

    assert result.quality.status == ArticleStatus.COMPLETE
    assert reporting in result.plain_text
    assert final_reporting in result.plain_text
    assert "CORONAVIRUS BUSINESS UPDATE" not in result.plain_text
    assert "Sign up here" not in result.plain_text
    assert "Latest coronavirus news" not in result.plain_text
    assert "Read more about the impact" not in result.plain_text
    assert "making key coronavirus coverage free" not in result.plain_text
    assert "substantive correction" in result.plain_text
    assert result.quality.images_selected == 0


