def test_ft_parser_removes_euro2day_partner_chrome_and_template_images():
    reporting = " ".join(
        [
            "The licensed Financial Times review remains substantive and "
            "complete for readers who need the historical context."
        ]
        * 8
    )
    canonical_url = "https://www.ft.com/content/euro2day-fixture"
    partner_url = (
        "https://www.euro2day.gr/ftcom_en/article-ft-en/1234/example.html"
    )
    capture = raw_capture("ft", canonical_url).model_copy(
        update={
            "final_url": partner_url,
            "selected_candidate": CaptureCandidate(
                provider=CaptureProvider.OTHER,
                snapshot_url=partner_url,
                status_code=200,
                mime_type="text/html",
            ),
        }
    )
    result = parse_article(
        f"""
        <html><head>
          <meta property="og:title" content="A syndicated FT review">
          <meta property="og:url" content="{partner_url}">
          <meta property="og:image"
            content="https://static.euro2day.gr/images/fbdefault.jpg">
          <meta property="article:published_time"
            content="2015-02-06T16:11:55Z">
        </head><body>
          <div class="article-content">
            <article id="textforresizing">
              <p>{reporting}</p>
            </article>
            <div class="sidebar"><p>Popular unrelated story</p></div>
            <div id="cpContent_pnlCopyright">
              <img src="/images/ft.png">
              <p>Copyright The Financial Times Limited 2015.</p>
            </div>
          </div>
        </body></html>
        """.encode(),
        publisher="ft",
        canonical_url=canonical_url,
        raw_capture=capture,
    )

    assert result.quality.status == ArticleStatus.COMPLETE
    assert "licensed Financial Times review" in result.plain_text
    assert "Popular unrelated story" not in result.plain_text
    assert "Copyright The Financial Times" not in result.plain_text
    assert result.quality.images_selected == 0
    assert result.extraction.parser_version == "ft-parser/0.8.69"


