def test_nyt_parser_preserves_interactive_figure_caption_prose():
    canonical_url = (
        "https://www.nytimes.com/interactive/2014/09/25/fashion/"
        "fashion-week-models-the-runway-revisited.html"
    )
    first_quote = " ".join(
        ["The model described a changing career backstage."] * 12
    )
    second_quote = " ".join(
        ["The designer explained how the runway work evolved."] * 12
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="The Runway Revisited">
      <meta property="article:published_time"
            content="2014-09-25T12:00:00Z">
    </head><body>
      <div class="interactive-graphic">
        <h3>Conrad Bromfield</h3>
        <figure><img src="https://static01.nyt.com/images/2014/09/25/fashion/one.jpg">
          <figcaption>
            <p>Conrad poses backstage before the presentation.</p>
            <p>{first_quote}</p>
          </figcaption>
        </figure>
        <h3>Sam Rollinson</h3>
        <figure><img src="https://static01.nyt.com/images/2014/09/25/fashion/two.jpg">
          <figcaption>
            <p>Sam prepares for the runway presentation.</p>
            <p>{second_quote}</p>
          </figcaption>
        </figure>
      </div>
    </body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=canonical_url,
        raw_capture=raw_capture("nyt", canonical_url),
    )

    assert result.quality.status.value == "complete"
    assert first_quote in result.plain_text
    assert second_quote in result.plain_text
    assert result.quality.body_characters >= len(first_quote) + len(second_quote)
    assert result.quality.images_selected == 2


def test_nyt_parser_removes_storyline_top_links_recirculation():
    canonical_url = (
        "https://www.nytimes.com/2012/02/18/sports/baseball/"
        "historical-baseball-report.html"
    )
    reporting = " ".join(["Historical baseball reporting sentence."] * 25)
    html = f"""
    <html><head>
      <meta property="og:title" content="A historical baseball report">
      <meta property="article:published_time"
            content="2012-02-18T12:00:00Z">
    </head><body><article>
      <section name="articleBody">
        <p>{reporting}</p>
        <div><section aria-labelledby="styln-toplinks-title"
                      role="complementary">
          <h2 id="styln-toplinks-title">The 2022 M.L.B. Season</h2>
          <h3>Strikeouts are boring! Besides that, they’re fascist.</h3>
          <ul><li><a href="https://www.nytimes.com/2022/example"
              >Professional baseball recirculation</a></li></ul>
        </section></div>
        <p>Final historical reporting paragraph.</p>
      </section>
    </article></body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=canonical_url,
        raw_capture=raw_capture("nyt", canonical_url),
    )

    assert result.quality.status.value == "complete"
    assert "Historical baseball reporting sentence." in result.plain_text
    assert "Final historical reporting paragraph." in result.plain_text
    assert "2022 M.L.B." not in result.plain_text
    assert "fascist" not in result.plain_text
    assert "Professional baseball recirculation" not in result.plain_text


