def test_nyt_parser_removes_legacy_columnist_identity_module_and_portrait():
    canonical_url = (
        "https://www.nytimes.com/2012/02/23/opinion/"
        "kristof-dodging-bombers-in-sudan.html"
    )
    thumbnail = (
        "http://graphics8.nytimes.com/images/2010/09/16/opinion/"
        "Kristof_New/Kristof_New-thumbStandard-v2.jpg"
    )
    inline_portrait = (
        "http://graphics8.nytimes.com/images/2010/09/16/opinion/"
        "Kristof_New/Kristof_New-articleInline-v2.jpg"
    )
    reporting = " ".join(
        ["The column reports from Sudan with detailed eyewitness accounts."]
        * 35
    )
    result = parse_article(
        f"""
        <html><head>
          <meta property="og:title" content="Dodging Bombers in Sudan">
          <meta property="article:published_time"
            content="2012-02-23T12:00:00Z">
          <meta property="og:image" content="{thumbnail}">
        </head><body><article><div itemprop="articleBody">
          <p>{reporting}</p>
          <p>The final editorial paragraph calls for an international
             response to the humanitarian crisis.</p>
          <div class="authorIdentification">
            <p>Example Reporter reported from Khartoum, and another
               contributor from Washington.</p>
          </div>
          <span itemprop="associatedMedia" itemscope
                itemtype="http://schema.org/ImageObject">
            <img itemprop="url" src="{inline_portrait}" width="190"
                 height="240" alt="">
          </span>
          <div class="authorIdentification">
            <p>•</p>
                <p>I invite you to visit my blog,
                  <a href="http://www.nytimes.com/ontheground">On the Ground</a>.
                  Please also join me on
                  <a href="http://www.facebook.com/kristof">Facebook</a> and
                  <a href="https://plus.google.com/example">Google+</a>, watch
                  my <a href="http://www.youtube.com/nicholaskristof">YouTube
                  videos</a> and follow me on
                  <a href="http://twitter.com/nickkristof">Twitter</a>.</p>
          </div>
        </div></article></body></html>
        """.encode(),
        publisher="nyt",
        canonical_url=canonical_url,
        raw_capture=raw_capture("nyt", canonical_url),
    )

    assert result.quality.status.value == "complete"
    assert "detailed eyewitness accounts" in result.plain_text
    assert "final editorial paragraph" in result.plain_text
    assert "Example Reporter reported from Khartoum" in result.plain_text
    assert "I invite you to visit my blog" not in result.plain_text
    assert "follow me on Twitter" not in result.plain_text
    assert result.quality.images_selected == 0
    assert all(
        image.original_url != inline_portrait for image in result.images
    )
    structured = next(
        image for image in result.images if image.original_url == thumbnail
    )
    assert structured.role == ImageRole.AUTHOR_AVATAR
    assert structured.should_archive is False
    assert "author-avatar-url" in structured.selection_reasons
    assert result.extraction.parser_version == "nyt-parser/0.8.158"


def test_reuters_generic_syndication_removes_benzinga_recirculation_tail():
    canonical_url = (
        "https://www.reuters.com/markets/us/"
        "goldman-sachs-expects-us-fed-deliver-three-rate-cuts-2025"
    )
    syndicated_url = "https://www.benzinga.com/markets/example"
    capture = raw_capture("reuters", canonical_url).model_copy(
        update={
            "selected_candidate": CaptureCandidate(
                provider=CaptureProvider.OTHER,
                snapshot_url=syndicated_url,
            ),
            "final_url": syndicated_url,
        }
    )
    reporting = " ".join(
        ["Reuters reporting explains the revised rate forecast."] * 10
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="Goldman Expects Three Rate Cuts">
      <meta property="og:url" content="{syndicated_url}">
    </head><body><article>
      <p>{reporting}</p>
      <p>The outlook reflects labor-market weakness and muted tariffs.</p>
      <p>See Also: An unrelated administration story</p>
      <p>Read Next:</p>
      <ul><li>Unrelated technology recommendation</li></ul>
      <p>Disclaimer: This content was produced with AI tools.</p>
      <p>© 2026 Benzinga.com. All rights reserved.</p>
    </article></body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="reuters",
        canonical_url=canonical_url,
        raw_capture=capture,
    )

    assert result.quality.status.value == "complete"
    assert "revised rate forecast" in result.plain_text
    assert "See Also" not in result.plain_text
    assert "Read Next" not in result.plain_text
    assert "Benzinga.com" not in result.plain_text


