def test_npr_parser_removes_inline_related_card_and_merges_renditions():
    html = b"""
    <html><head>
      <meta property="og:title" content="How To Lose The Senate In 82 Days">
      <meta property="article:published_time" content="2016-08-18T00:00:00Z">
      <meta property="og:image" content="https://media.npr.org/assets/img/2016/08/17/ap_998463934978_wide-1da5c6eea04ec3d298695fa94a7fbf4ae798d4ac.jpg?s=1400">
    </head><body><div id="storytext">
      <div class="bucketwrap image large">
        <div class="imagewrap">
          <img src="https://media.npr.org/assets/img/2016/08/17/ap_998463934978-985102d9f46b27fc0a6f1fd8eb5d51166ce6faf7-s1100.jpg"
               data-original="https://media.npr.org/assets/img/2016/08/17/ap_998463934978-985102d9f46b27fc0a6f1fd8eb5d51166ce6faf7-s1200.jpg">
        </div>
        <div class="captionwrap">The senators face competitive elections.</div>
        <div class="creditwrap">Charles Krupa/AP</div>
      </div>
      <p>Editorial reporting before the inline recommendation.</p>
      <div class="bucketwrap internallink insettwocolumn inset2col">
        <div class="bucket img">
          <img src="https://media.npr.org/assets/img/2016/08/16/gettyimages-484141782_sq-2dbdc75159265fef93ac0e716513a595d4b15ce3-s100.jpg">
        </div>
        <div class="bucketblock">
          <h3 class="slug">Politics</h3>
          <h3>Is Rural Resentment Driving Voters To Donald Trump?</h3>
        </div>
      </div>
      <p>Editorial reporting after the inline recommendation remains intact.</p>
    </div></body></html>
    """
    article = parse_article(
        html,
        publisher="npr",
        canonical_url=(
            "https://www.npr.org/2016/08/18/490378267/"
            "how-to-lose-the-senate-in-82-days"
        ),
    )
    assert "Politics" not in article.plain_text
    assert "Rural Resentment" not in article.plain_text
    assert "reporting before" in article.plain_text
    assert "reporting after" in article.plain_text
    selected = [image for image in article.images if image.should_archive]
    assert len(selected) == 1
    assert len(selected[0].candidate_urls) == 3
    assert selected[0].caption == "The senators face competitive elections."
    assert selected[0].credit == "Charles Krupa/AP"


