def test_ap_parser_removes_heading_underscore_separator():
    html = b"""
    <html><head>
      <meta property="og:title" content="AP report">
      <meta property="article:published_time" content="2023-07-14T00:00:00Z">
    </head><body><article>
      <p>The opening paragraph contains substantial reporting and context
      for readers following the story and its consequences.</p>
      <h2>__</h2>
      <p>The closing paragraph adds more verified details and attribution
      for the complete archived article.</p>
    </article></body></html>
    """
    result = parse_article(
        html,
        publisher="ap",
        canonical_url="https://apnews.com/article/heading-separator",
    )
    assert result.quality.status.value == "complete"
    assert "__" not in result.plain_text
    assert "opening paragraph" in result.plain_text
    assert "closing paragraph" in result.plain_text
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_removes_live_update_read_more_module():
    html = b"""
    <html><head>
      <meta property="og:title" content="The latest election updates">
      <meta property="article:published_time" content="2020-11-01T00:00:00Z">
    </head><body><article><div class="RichTextStoryBody">
      <p>The opening update contains substantial reporting and context for
      readers following the election results and the public response.</p>
      <p>Read more:</p>
      <p>- An unrelated recommended election story</p>
      <p>- Another related headline from the live desk</p>
      <p>___</p>
      <p>HERE'S WHAT ELSE HAPPENING:</p>
      <p>The closing update contains additional reporting and must survive
      removal of the adjacent recommendation module.</p>
    </div></article></body></html>
    """
    result = parse_article(
        html,
        publisher="ap",
        canonical_url="https://apnews.com/article/live-update-read-more",
    )
    assert result.quality.status.value == "complete"
    assert "Read more" not in result.plain_text
    assert "unrelated recommended" not in result.plain_text
    assert "Another related headline" not in result.plain_text
    assert "closing update contains additional reporting" in result.plain_text
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_removes_inline_related_navigation_label():
    html = b"""
    <html><head>
      <meta property="og:title" content="AP politics report">
      <meta property="article:published_time" content="2018-04-28T00:00:00Z">
    </head><body><article>
      <p>The opening paragraph contains the complete editorial report.</p>
      <p><span class="LinkEnhancement"><a href="https://example.com/related">
        RELATED:
      </a></span></p>
      <p>: A related headline should remain as quoted context.</p>
      <p>The closing paragraph completes the report.</p>
    </article></body></html>
    """
    result = parse_article(
        html,
        publisher="ap",
        canonical_url="https://apnews.com/article/ap-politics-report",
    )
    assert "RELATED" not in result.plain_text
    assert "related headline should remain" in result.plain_text
    assert "opening paragraph" in result.plain_text
    assert "closing paragraph" in result.plain_text


def test_ap_parser_removes_earnings_interactive_controls():
    html = b"""
    <html><head>
      <meta property="og:title" content="Company earnings report">
      <meta property="article:published_time" content="2019-04-28T00:00:00Z">
    </head><body><article><div class="RichTextStoryBody">
      <p>The earnings report describes the company's results and outlook for
      investors, employees and customers in the coming year.</p>
      <form class="earnings-filter"><input name="quarter" value="Q4">
        <button>Apply</button></form>
      <p>The closing paragraph explains management's expectations and the
      risks that could affect future performance.</p>
    </div></article></body></html>
    """
    result = parse_article(
        html,
        publisher="ap",
        canonical_url="https://apnews.com/earnings-example",
    )
    assert result.quality.status.value == "complete"
    assert "earnings report describes" in result.plain_text
    assert "management's expectations" in result.plain_text
    assert "<form" not in result.body_html
    assert "<input" not in result.body_html
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_extracts_hosted_ap_legacy_story_template():
    html = b"""
    <html><body>
      <table class="ap-story-table hnews hentry item">
        <tr><td><div class="body">
          <div class="timestamp updated" title="2011-01-11T1221Z">
            Jan 11, 12:21 PM EST
          </div>
          <p class="body">
            <span class="headline entry-title">
              4 dead as forces raid Ivory Coast neighborhood
            </span>
          </p>
          <span class="byline">By <span class="author vcard">
            <span class="fn">RUKMINI CALLIMACHI</span>
          </span></span>
        </div></td></tr>
        <tr><td><span class="entry-content">
          <img src="https://analytics.apnewsregistry.com/pixel.gif"
               width="1" height="1" alt="">
          <p class="ap-story-p">ABIDJAN, Ivory Coast (AP) -- Security
          forces cordoned off a neighborhood before residents described
          sustained gunfire and several deaths during the operation.</p>
          <p class="ap-story-p">United Nations peacekeepers arriving in a
          convoy were forced to turn around while witnesses described the
          confrontation and its aftermath in detail.</p>
          <p class="ap-story-p">---</p>
          <p class="ap-story-p">Associated Press writer Example Reporter
          contributed to this report.</p>
        </span>
        <p class="ap-story-p">Copyright boilerplate outside the story.</p>
        </td></tr>
      </table>
    </body></html>
    """

    result = parse_article(
        html,
        publisher="ap",
        canonical_url=(
            "http://hosted.ap.org/dynamic/stories/A/AF_IVORY_COAST"
            "?SITE=AP&CTIME=2011-01-11-12-21-19"
        ),
    )

    assert result.quality.status.value == "complete"
    assert result.headline == (
        "4 dead as forces raid Ivory Coast neighborhood"
    )
    assert result.published_at is not None
    assert result.published_at.isoformat() == "2011-01-11T12:21:00+00:00"
    assert [author.name for author in result.authors] == [
        "RUKMINI CALLIMACHI"
    ]
    assert "Security forces cordoned off" in result.plain_text
    assert "contributed to this report" in result.plain_text
    assert "Copyright boilerplate" not in result.plain_text
    assert "---" not in result.plain_text
    assert len(result.images) == 1
    assert result.images[0].role.value == "tracking"
    assert result.images[0].should_archive is False
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_extracts_bigstory_timestamp_and_body():
    html = b"""
    <html><body>
      <h1>007 exhibition looks at screen spy as style icon</h1>
      <div class="article-data">
        <div class="field-name-field-byline-original">By JILL LAWLESS</div>
        <span class="updated" title="2012-07-05T12:27:51-04:00">
          Jul. 5 12:27 PM EDT
        </span>
      </div>
      <div class="node-body"><div class="node-content">
        <p>LONDON (AP) -- A major exhibition examines the clothing,
        vehicles, props and visual design that shaped the screen spy over
        five decades of films and popular culture.</p>
        <p>The archived report contains enough additional reporting to
        distinguish the complete article from a navigation shell, teaser,
        photo caption, advertisement, or related-story card.</p>
      </div></div>
    </body></html>
    """

    result = parse_article(
        html,
        publisher="ap",
        canonical_url=(
            "https://bigstory.ap.org/article/"
            "007-exhibition-looks-screen-spy-style-icon"
        ),
    )

    assert result.quality.status.value == "complete"
    assert result.published_at is not None
    assert result.published_at.astimezone(timezone.utc).isoformat() == (
        "2012-07-05T16:27:51+00:00"
    )
    assert "major exhibition examines" in result.plain_text
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_extracts_legacy_yahoo_distribution_story():
    html = b"""
    <html><head>
      <meta name="title" content="Clarification: Piers Morgan story">
    </head><body>
      <div id="yn-story">
        <h1 id="yn-title">Clarification: Piers Morgan story</h1>
        <div class="byline">
          <cite class="vcard"><span class="fn org"></span></cite>
          <abbr title="2011-01-09T17:41:58-0800" class="timedate">
            Sun Jan 9, 8:41 pm ET
          </abbr>
        </div>
        <div class="yn-story-content">
          <p>PASADENA, Calif. -- In a Jan. 6 story, The Associated Press
          reported CNN anchor Piers Morgan's claim about an interview. The
          clarification explains the election result and corrects the prior
          report with enough context to stand as the complete AP item.</p>
        </div>
        <div class="yn-share-social">Follow Yahoo News on social media.</div>
        <div class="comments"><p>This user comment is not article text.</p></div>
      </div>
    </body></html>
    """

    result = parse_article(
        html,
        publisher="ap",
        canonical_url=(
            "http://news.yahoo.com/s/ap/20110110/"
            "ap_on_en_tv/us_tv_cnn_morgan"
        ),
        allow_generic_syndication=True,
    )

    assert result.quality.status.value == "complete"
    assert result.headline == "Clarification: Piers Morgan story"
    assert result.published_at is not None
    assert result.published_at.astimezone(timezone.utc).isoformat() == (
        "2011-01-10T01:41:58+00:00"
    )
    assert "The Associated Press reported" in result.plain_text
    assert "Follow Yahoo News" not in result.plain_text
    assert "user comment" not in result.plain_text
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_extracts_google_hosted_distribution_story():
    canonical_url = (
        "http://www.google.com/hostednews/ap/article/"
        "ALeqM5g3GDCPdLfq2U7PRBzbJTC12i2JZg?docId=example"
    )
    capture = raw_capture("ap", canonical_url).model_copy(
        update={
            "published_at": datetime(
                2011,
                11,
                30,
                16,
                9,
                tzinfo=timezone.utc,
            )
        }
    )
    html = b"""
    <html><head>
      <meta property="og:title"
            content="Ex Colo. sheriff accused of offering meth for sex">
    </head><body>
      <div id="hostednews-article">
        <div class="g-unit g-first"><div class="hn-copy">
          <div class="g-section">
            <div id="hn-headline">
              Ex Colo. sheriff accused of offering meth for sex
            </div>
            <p class="hn-byline">
              By STEVEN K. PAULSON, Associated Press - 2 days ago
            </p>
            <p>CENTENNIAL, Colo. (AP) -- The former sheriff was known for
            his public service and concern about teenage drug use before the
            allegations described in this complete archived report.</p>
            <p>The report contains enough additional detail to distinguish
            the article body from a navigation shell or summary card.</p>
            <p id="hn-distributor-copyright">
              Copyright 2011 The Associated Press. All rights reserved.
            </p>
          </div>
          <div class="g-section" id="rn-section">
            <h4>Related articles</h4><p>Unrelated recommendation.</p>
          </div>
        </div></div>
      </div>
    </body></html>
    """

    result = parse_article(
        html,
        publisher="ap",
        canonical_url=canonical_url,
        raw_capture=capture,
        allow_generic_syndication=True,
    )

    assert result.quality.status.value == "complete"
    assert result.headline == (
        "Ex Colo. sheriff accused of offering meth for sex"
    )
    assert [author.name for author in result.authors] == [
        "STEVEN K. PAULSON"
    ]
    assert result.published_at == capture.published_at
    assert "former sheriff was known" in result.plain_text
    assert "Related articles" not in result.plain_text
    assert "Copyright 2011" not in result.plain_text
    assert "Associated Press - 2 days ago" not in result.plain_text
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_extracts_huffpost_wire_distribution_story():
    canonical_url = (
        "https://www.huffingtonpost.com/huff-wires/20110104/"
        "af-kenya-corruption"
    )
    html = b"""
    <html><head>
      <title>Kenyan minister resigns over car imports scandal</title>
    </head><body>
      <div class="entry"><div class="entry_right">
        <h1><a>Kenyan minister resigns over car imports scandal</a></h1>
        <div class="comments_datetime"><p>
          <a class="wire_author">TOM MALITI</a> |
          January 4, 2011 10:06 AM EST |
          <span class="ap"><img alt="AP"></span>
        </p></div>
        <div class="entry_content">
          <p>NAIROBI, Kenya -- Kenya's industrialization minister resigned
          on Tuesday over a car imports scandal and said he looked forward
          to presenting his defense in court.</p>
          <div class="contin_below">Story continues below</div>
          <div class="adver_cont_below">
            <span class="mid_article_ad_label">Advertisement</span>
            <div class="ad_wrapper">Advertisement frame</div>
          </div>
          <p>The anti-corruption commission had investigated the imports,
          and this second paragraph completes the archived AP wire item.</p>
        </div>
      </div></div>
    </body></html>
    """

    result = parse_article(
        html,
        publisher="ap",
        canonical_url=canonical_url,
        allow_generic_syndication=True,
    )

    assert result.quality.status.value == "complete"
    assert result.headline == (
        "Kenyan minister resigns over car imports scandal"
    )
    assert [author.name for author in result.authors] == ["TOM MALITI"]
    assert result.published_at is not None
    assert result.published_at.astimezone(timezone.utc).isoformat() == (
        "2011-01-04T15:06:00+00:00"
    )
    assert "industrialization minister resigned" in result.plain_text
    assert "Story continues below" not in result.plain_text
    assert "Advertisement" not in result.plain_text
    assert result.extraction.parser_version == "ap-parser/0.6.27"


def test_ap_parser_extracts_story_html_from_embedded_state():
    story_html = "".join(
        f"<p>Embedded AP reporting paragraph {index} provides substantive "
        "details about the archived story.</p>"
        for index in range(1, 7)
    )
    state = {
        "content": {
            "data": {
                "urn:publicid:ap.org:example": {
                    "storyHTML": story_html,
                }
            }
        }
    }
    html = f"""
    <html>
      <head>
        <meta property="og:title" content="Embedded AP article">
        <meta property="article:published_time"
              content="2021-05-28T07:24:28Z">
      </head>
      <body>
        <script>
          window['titanium-config'] = {{"env": "prod"}};
          window['titanium-state'] = {json.dumps(state)};
        </script>
      </body>
    </html>
    """.encode()

    article = parse_article(
        html,
        publisher="ap",
        canonical_url="https://apnews.com/article/example",
    )

    assert article.quality.status.value == "complete"
    assert len(article.blocks) == 6
    assert "paragraph 6" in article.plain_text
    assert article.extraction.parser_version == "ap-parser/0.6.27"


