def test_ap_parser_excludes_default_lead_and_page_promo_images():
    structured = {
        "@type": "NewsArticle",
        "headline": "AP report with current template recirculation",
        "datePublished": "2023-11-12T12:00:00Z",
        "image": [
            {
                "url": (
                    "https://dims.apnews.com/dims4/default/36eef90/"
                    "2147483647/strip/false/crop/1281x854+0+0/"
                    "resize/980x653!/quality/90/?url=https%3A%2F%2F"
                    "assets.apnews.com%2F0c%2F94%2Fcbc970464ba8bfbc"
                    "6042dd7cdd78%2Fthe-ap-default-image-2026.png"
                )
            }
        ],
    }
    reporting = " ".join(["Substantive AP reporting sentence."] * 30)
    html = f"""
    <html><head><script type="application/ld+json">
      {json.dumps(structured)}
    </script></head><body>
      <div class="RichTextStoryBody">
        <p>{reporting}</p>
        <h2>Up next</h2>
        <p>The next opponent and game time are part of the sports report.</p>
        <p>AP MLB: https://apnews.com/hub/mlb and
           https://twitter.com/AP_Sports</p>
        <p>AP college football: https://apnews.com/hub/college-football and
           https://apnews.com/hub/ap-top-25-college-football-poll</p>
        <p>▶ View and download the men’s NCAA Tournament bracket</p>
        <figure>
          <img src="https://dims.apnews.com/editorial-599.jpg"
               width="599" height="399" alt="Editorial photograph">
        </figure>
        <div class="PagePromo" data-gtm-region="Related story">
          <div class="PagePromo-media">
            <a class="Link" href="https://apnews.com/article/related-story">
              <picture data-crop="small-3x2-nocrop">
                <source width="135" height="90"
                        srcset="https://dims.apnews.com/related-135.jpg 1x,
                                https://dims.apnews.com/related-270.jpg 2x">
                <img src="https://dims.apnews.com/related-135.jpg"
                     width="135" height="90" alt="Related story image">
              </picture>
            </a>
          </div>
          <div class="PagePromo-title">Unrelated recommended story</div>
        </div>
      </div>
    </body></html>
    """.encode()

    article = parse_article(
        html,
        publisher="ap",
        canonical_url="https://apnews.com/article/current-template",
    )

    assert article.quality.status.value == "complete"
    assert reporting in article.plain_text
    assert "Up next" in article.plain_text
    assert "next opponent and game time" in article.plain_text
    assert "AP MLB:" not in article.plain_text
    assert "AP college football:" not in article.plain_text
    assert "NCAA Tournament bracket" not in article.plain_text
    assert "Unrelated recommended story" not in article.plain_text
    assert [image.original_url for image in article.images] == [
        "https://dims.apnews.com/editorial-599.jpg"
    ]


