@pytest.mark.parametrize(
    ("footer_html", "expected_status"),
    [
        (
            """
            <footer class="story-footer story-content">
              <p class="story-print-citation">
                A version of this article appears in print on March 26, 2017,
                on Page M238 of T Magazine.
              </p>
            </footer>
            """,
            "complete",
        ),
        ("", "partial"),
    ],
)
def test_nyt_parser_requires_completed_legacy_tmag_format_short_page(
    footer_html: str,
    expected_status: str,
):
    html = f"""
    <html class="section-t-magazine format-short app-article">
      <head>
        <meta property="og:title" content="Bondage Goes Mainstream">
        <meta property="og:image"
              content="https://static01.nyt.com/images/2017/tmag-bondage.jpg">
        <meta property="article:published_time"
              content="2017-03-09T00:00:00Z">
      </head>
      <body><article id="story" class="story theme-main">
        <div class="story-body story-body-1">
          <p class="story-body-text story-content"
             data-para-count="65" data-total-count="65">
            <em>This season is all about men’s suiting that’s fit to be tied.</em>
          </p>
        </div>
        <figure itemprop="associatedMedia">
          <img itemprop="url"
               src="https://static01.nyt.com/images/2017/tmag-bondage.jpg">
          <figcaption>Illustrations by Konstantin Kakanias</figcaption>
        </figure>
        <div class="story-body story-body-2">{footer_html}</div>
      </article></body>
    </html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2017/03/09/t-magazine/fashion/"
            "bondage-goes-mainstream.html"
        ),
    )

    assert result.content_type.value == "article"
    assert result.quality.status.value == expected_status
    assert result.quality.images_selected == 1
    assert "This season is all about men’s suiting" in result.plain_text
    assert ("body-too-short" in result.quality.warnings) == (
        expected_status == "partial"
    )
    assert result.extraction.parser_version == "nyt-parser/0.8.158"


@pytest.mark.parametrize(
    ("end_marker_variant", "expected_status"),
    [
        ("next-in", "complete"),
        ("legacy-footer", "complete"),
        ("legacy-footer-without-page-footer", "partial"),
        ("none", "partial"),
    ],
)
def test_nyt_parser_requires_completed_legacy_opinion_visual_short(
    end_marker_variant: str,
    expected_status: str,
):
    body = "Will China let the beast into the house?"
    next_in = ""
    story_footer = ""
    whats_next = ""
    page_footer = ""
    if end_marker_variant == "next-in":
        next_in = '<nav id="next-in" class="next-in story-content"></nav>'
        whats_next = '<section id="whats-next" class="whats-next"></section>'
    elif end_marker_variant.startswith("legacy-footer"):
        story_footer = (
            '<footer class="story-footer story-content">'
            '<div class="story-meta"></div></footer>'
        )
        whats_next = '<section id="whats-next" class="whats-next"></section>'
        if end_marker_variant == "legacy-footer":
            page_footer = '<footer id="page-footer" role="contentinfo"></footer>'
    html = f"""
    <html class="section-opinion format-short tone-opinion has-large-lede">
      <head>
        <meta property="og:title" content="The Dark Guest">
        <meta property="og:description" content="{body}">
        <meta property="article:published" content="2014-05-18">
        <meta name="author" content="">
        <meta name="byl" content="">
      </head>
      <body><main>
        <article id="story" class="story theme-main">
          <div class="lede-container">
            <figure itemprop="associatedMedia">
              <img itemprop="url"
                   src="http://static01.nyt.com/images/2014/05/18/opinion/dark-guest.jpg">
            </figure>
          </div>
          <p class="story-body-text story-content" itemprop="articleBody"
             data-para-count="40" data-total-count="40">{body}</p>
          {next_in}
          {story_footer}
        </article>
        {whats_next}
      </main>{page_footer}</body>
    </html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2014/05/18/opinion/"
            "the-dark-guest.html"
        ),
    )

    assert result.content_type.value == "opinion"
    assert result.quality.status.value == expected_status
    assert result.quality.images_selected == 1
    assert result.plain_text == body
    assert ("body-too-short" in result.quality.warnings) == (
        expected_status == "partial"
    )
    assert result.extraction.parser_version == "nyt-parser/0.8.158"


