def test_nyt_parser_preserves_modern_document_pages_and_pdf_link():
    pages = "".join(
        f"""
        <img class="g-doc-image lazyload"
             src="https://static01.nyt.com/packages/flash/multimedia/ICONS/transparent.png"
             data-src="https://int.nyt.com/data/documenttools/example/{page}/output-{page}.png"
             width="1089" height="1408">
        """
        for page in range(1, 4)
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="Read the document">
      <meta name="description" content="The indictment is reproduced below.">
      <meta property="article:published_time" content="2020-08-20T00:00:00Z">
    </head><body>
      <article id="interactive" class="interactive">
        <section class="interactive-content">
          <div class="interactive-body">
            <div class="g-graphic">
              <div class="g-doc-header">
                <p>A PDF version of this document is available below.</p>
                <a href="https://int.nyt.com/data/documenttools/example/full.pdf">
                  <h2>Download the original document (pdf)</h2>
                </a>
              </div>
              <div class="g-doc">{pages}</div>
            </div>
          </div>
        </section>
      </article>
    </body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/interactive/2020/08/20/us/"
            "example-doc.html"
        ),
    )

    assert result.quality.status.value == "complete"
    assert result.content_type.value == "interactive"
    page_blocks = [
        block for block in result.blocks if block.type.value == "image"
    ]
    assert len(page_blocks) == 3
    images_by_id = {image.asset_id: image for image in result.images}
    assert [images_by_id[block.asset_id].original_url for block in page_blocks] == [
        f"https://int.nyt.com/data/documenttools/example/{page}/output-{page}.png"
        for page in range(1, 4)
    ]
    assert result.blocks[-1].embed_url == (
        "https://int.nyt.com/data/documenttools/example/full.pdf"
    )
    assert "transparent.png" not in result.body_html


