def test_nyt_parser_keeps_each_dynamic_chart_in_multi_image_figure():
    chart_base = (
        "http://markets.on.nytimes.com/research/tools/builder/api.asp"
    )
    reporting = " ".join(
        ["Amazon reported quarterly earnings and explained its outlook."] * 10
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="Losses Jump at Amazon">
      <meta property="article:published_time" content="2014-10-24T00:00:00Z">
    </head><body><article id="story" class="story theme-main">
      <p>{reporting}</p>
      <figure id="amazon-stock-chart" class="interactive-embedded">
        <div class="interactive-graphic">
          <div id="nyttech-stock-chart">
            <img src="{chart_base}?sym=AMZN&amp;duration=1&amp;w=300&amp;h=200">
            <div class="caption">Amazon's stock activity today.</div>
          </div>
          <div id="nyttech-stock-chart">
            <img src="{chart_base}?sym=AMZN&amp;duration=90&amp;w=300&amp;h=200">
            <div class="caption">Amazon trading over the last three months.</div>
          </div>
        </div>
      </figure>
    </article></body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2014/10/24/technology/"
            "amazon-loss-quarterly-earnings.html"
        ),
    )

    charts = [
        image
        for image in result.images
        if "markets.on.nytimes.com" in image.original_url
    ]
    assert len(charts) == 2
    assert len({image.asset_id for image in charts}) == 2
    assert {image.caption for image in charts} == {
        "Amazon's stock activity today.",
        "Amazon trading over the last three months.",
    }
    assert sum(
        block.type == BlockType.IMAGE
        and block.asset_id in {image.asset_id for image in charts}
        for block in result.blocks
    ) == 2
    assert result.extraction.parser_version == "nyt-parser/0.8.158"


