def test_nyt_parser_accepts_migrated_metadata_only_opinion_cartoon():
    canonical_url = (
        "https://www.nytimes.com/2014/03/26/opinion/"
        "chappatte-obama-is-welcomed-back-to-europe.html"
    )
    description = "But it is not quite business as usual."
    payload = {
        "initialState": {
            "Article:cartoon": {
                "__typename": "Article",
                "url": canonical_url,
                "headline": {"id": "Headline:cartoon"},
                "summary": description,
                "firstPublished": "2014-03-26T00:00:00Z",
                "wordCount": 9,
                "bylines": [],
            },
            "Headline:cartoon": {"default": "Obama in Europe"},
        }
    }
    lead_image = (
        "https://static01.nyt.com/images/2014/03/26/opinion/"
        "26chappatte/26chappatte-articleLarge.jpg"
    )
    html = f"""
    <html><head>
      <meta property="article:section" content="Opinion">
      <meta property="og:image" content="{lead_image}">
      <script>window.__preloadedData = {json.dumps(payload)};</script>
    </head><body><article><section name="articleBody">
      <p>{description}</p>
    </section></article></body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=canonical_url,
    )

    assert result.content_type.value == "opinion"
    assert result.quality.status.value == "complete"
    assert result.plain_text == description
    assert result.quality.images_selected == 1
    assert result.images[0].original_url == lead_image

    ordinary_short = parse_article(
        html.replace(b'"wordCount": 9', b'"wordCount": 200'),
        publisher="nyt",
        canonical_url=canonical_url,
    )
    assert ordinary_short.quality.status.value == "partial"


def test_nyt_parser_recovers_preloaded_single_image_editorial_cartoon():
    canonical_url = (
        "https://www.nytimes.com/2015/06/29/opinion/up-up-and-away.html"
    )
    image_url = (
        "https://static01.nyt.com/images/2015/06/29/opinion/29heng/"
        "29heng-superJumbo.jpg"
    )
    body_id = "$Article:cartoon.sprinkledBody"
    header_id = f"{body_id}.content.0"
    image_block_id = f"{header_id}.ledeMedia"
    image_id = "Image:cartoon"
    crop_id = f"{image_id}.crop.0"
    state = {
        body_id: {
            "__typename": "DocumentBlock",
            "content@filterEmpty": [{"id": header_id}],
        },
        header_id: {
            "__typename": "HeaderLegacyBlock",
            "ledeMedia": {"id": image_block_id},
        },
        image_block_id: {
            "__typename": "ImageBlock",
            "media": {"id": image_id},
        },
        image_id: {
            "__typename": "Image",
            'crops({"renditionNames":["articleLarge","jumbo","superJumbo","articleInline","popup"]})': [
                {"id": crop_id}
            ],
        },
        crop_id: {"renditions": [{"id": "ImageRendition:cartoon"}]},
        "ImageRendition:cartoon": {
            "__typename": "ImageRendition",
            "url": image_url,
            "width": 2048,
            "height": 1478,
        },
        "$Article:cartoon.printInformation": {
            "headline@stripHtml": "Editorial Cartoon"
        },
    }
    html = f"""
    <html><head>
      <meta property="og:title" content="Up, Up and Away!">
      <meta name="description"
            content="Obama gets a big lift in his quest for a trade accord.">
      <meta property="og:image"
            content="https://static01.nyt.com/images/2015/06/29/opinion/29heng/29heng-facebookJumbo.jpg">
      <meta property="article:published_time" content="2015-06-28T21:53:40Z">
      <script>window.__preloadedData = {json.dumps({"initialState": state})};</script>
    </head><body><article><section name="articleBody">
      <p>Obama gets a big lift in his quest for a trade accord.</p>
    </section></article></body></html>
    """.encode()

    result = parse_article(html, publisher="nyt", canonical_url=canonical_url)

    assert result.content_type == ContentType.GALLERY
    assert result.quality.status == ArticleStatus.COMPLETE
    assert result.quality.images_selected == 1
    assert result.images[0].original_url == image_url
    assert result.extraction.parser_version == "nyt-parser/0.8.158"


