def test_nyt_parser_does_not_replace_substantive_article_with_gallery():
    images = [
        {
            "__typename": "ImageBlock",
            "media": {
                "__typename": "Image",
                "caption": {"text": f"Scene {index}"},
                "crops": [{
                    "renditions": [{
                        "__typename": "ImageRendition",
                        "url": f"https://static01.nyt.com/scene-{index}.jpg",
                        "width": 1200,
                        "height": 800,
                    }]
                }],
            },
        }
        for index in range(3)
    ]
    payload = json.dumps({
        "initialData": {
            "data": {
                "article": {"sprinkledBody": {"content": images}}
            }
        },
        "initialState": {},
    })
    paragraphs = "".join(
        "<p>This is substantive reporting paragraph "
        f"{index}, with enough original context and detail to prove that "
        "the prose article must remain the selected body even when its "
        "preloaded data contains several photographs.</p>"
        for index in range(4)
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="A Report With Several Photos">
      <meta property="article:published_time"
            content="2019-06-23T00:00:00Z">
    </head><body>
      <article><section name="articleBody">{paragraphs}</section></article>
      <script>window.__preloadedData = {payload};</script>
    </body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2019/06/23/nyregion/"
            "a-report-with-several-photos.html"
        ),
    )

    assert result.content_type.value == "article"
    assert result.quality.status.value == "complete"
    assert result.quality.body_characters > 500
    assert "substantive reporting paragraph 3" in result.plain_text


def test_nyt_parser_appends_explicit_slideshow_to_substantive_article():
    images = [
        {
            "__typename": "ImageBlock",
            "media": {
                "__typename": "Image",
                "credit": "Gallery photographer",
                "caption": {"text": f"Fashion event {index}"},
                "crops": [{
                    "renditions": [{
                        "__typename": "ImageRendition",
                        "url": (
                            "https://static01.nyt.com/images/2018/fashion/"
                            f"party-{index}-superJumbo.jpg"
                        ),
                        "width": 1200,
                        "height": 800,
                    }]
                }],
            },
        }
        for index in range(3)
    ]
    payload = json.dumps({
        "initialData": {
            "data": {
                "article": {"sprinkledBody": {"content": images}}
            }
        },
        "initialState": {},
    })
    paragraphs = "".join(
        "<p>Fashion week reporting preserves interviews, event context and "
        f"scene details in substantive paragraph {index}.</p>"
        for index in range(5)
    )
    html = f"""
    <html><head>
      <meta property="og:title" content="The Party Must Go On">
      <meta property="article:published_time"
            content="2018-02-13T00:00:00Z">
    </head><body><article>
      <header><a href="/slideshow/2018/02/13/fashion/parties.html">
        <span>30 Photos</span><span>View Slide Show</span>
      </a></header>
      <section name="articleBody">{paragraphs}</section>
    </article>
    <script>window.__preloadedData = {payload};</script>
    </body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2018/02/13/fashion/"
            "new-york-fashion-week-parties.html"
        ),
    )

    assert result.content_type.value == "gallery"
    assert result.quality.status.value == "complete"
    assert "substantive paragraph 4" in result.plain_text
    assert result.quality.images_selected == 3
    assert [
        block.caption
        for block in result.blocks
        if block.type.value == "image"
    ] == ["Fashion event 0", "Fashion event 1", "Fashion event 2"]


