def test_nyt_parser_preserves_books_review_sketchbook_illustration():
    canonical_url = (
        "https://www.nytimes.com/2018/06/15/books/review/"
        "children-library-etiquette.html"
    )
    paragraph = (
        "An illustrated reminder of what happens when kids are left to roam "
        "the stacks of a library."
    )
    image_url = (
        "https://static01.nyt.com/images/2018/06/17/books/review/"
        "17Sketchbook-Snider/17Sketchbook-Snider-articleLarge.jpg"
    )
    social_image_url = (
        "https://static01.nyt.com/images/2018/06/17/books/review/"
        "17Sketchbook-Snider/17Sketchbook-Snider-facebookJumbo.jpg"
    )
    payload = {
        "initialState": {
            "Article:sketchbook": {
                "__typename": "Article",
                "url": canonical_url,
                "headline": {"id": "Headline:sketchbook"},
                "summary": (
                    "Grant Snider provides an illustrated reminder of what "
                    "happens when kids roam a library."
                ),
                "firstPublished": "2018-06-15T09:00:04.642Z",
                "wordCount": 17,
                "bylines": [{"id": "Byline:sketchbook"}],
            },
            "Headline:sketchbook": {
                "default": "Left to Their Own (Literary) Devices"
            },
            "Byline:sketchbook": {
                "renderedRepresentation": "By Grant Snider"
            },
        }
    }
    html = f"""
    <html><head>
      <meta property="og:title"
            content="Left to Their Own (Literary) Devices">
      <meta property="og:description"
            content="Grant Snider provides an illustrated reminder.">
      <meta property="og:image" content="{social_image_url}">
      <script>window.__preloadedData = {json.dumps(payload)};</script>
    </head><body><article id="story">
      <p class="section-label">Sketchbook</p>
      <div class="StoryBodyCompanionColumn"><p><em>{paragraph}</em></p></div>
      <figure itemprop="associatedMedia">
        <img itemprop="url" src="{image_url}">
        <figcaption><span>Image</span><span>Credit</span>
          <span>Grant Snider</span></figcaption>
      </figure>
      <div class="StoryBodyCompanionColumn"></div>
    </article></body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="nyt",
        canonical_url=canonical_url,
    )

    assert result.content_type.value == "gallery"
    assert result.quality.status.value == "complete"
    assert result.plain_text.startswith(paragraph)
    assert "Grant Snider" in result.plain_text
    assert [block.type.value for block in result.blocks] == [
        "paragraph",
        "image",
    ]
    assert image_url in result.body_html
    assert result.quality.images_selected == 1
    assert result.images[0].original_url == image_url
    assert result.extraction.parser_version == "nyt-parser/0.8.158"

    ordinary_short = parse_article(
        html.replace(b'"wordCount": 17', b'"wordCount": 200'),
        publisher="nyt",
        canonical_url=canonical_url,
    )
    assert ordinary_short.quality.status.value == "partial"
    assert all(block.type.value != "image" for block in ordinary_short.blocks)


