def test_nyt_parser_rejects_reused_non_editorial_structured_images():
    cases = (
        (
            "https://www.nytimes.com/2014/03/21/business/corporate-lies.html",
            "https://static01.nyt.com/images/2014/01/31/business/"
            "norrispic/norrispic-superJumbo.jpg",
        ),
        (
            "https://www.nytimes.com/2020/04/10/business/stock-market.html",
            "https://www.nytimes.com/newsgraphics/2020/04/09/"
            "corona-virus-social-images-by-section/assets/Business_promo.jpg",
        ),
        (
            "https://www.nytimes.com/interactive/2024/11/05/us/elections/"
            "results-georgia-us-house-11.html",
            "https://static01.nyt.com/images/2024/11/06/"
            "05election-2024-reporter-updates-F07ULM8TT6K/"
            "05election-2024-reporter-updates-F07ULM8TT6K-superJumbo.png",
        ),
    )
    for canonical_url, image_url in cases:
        result = parse_article(
            f"""
            <html><head>
              <meta property="og:title" content="A complete NYT report">
              <meta property="article:published_time"
                content="2024-11-05T12:00:00Z">
              <meta property="og:image" content="{image_url}">
            </head><body><main class="interactive-body">
              <p>{'Substantive election reporting sentence. ' * 25}</p>
            </main></body></html>
            """.encode(),
            publisher="nyt",
            canonical_url=canonical_url,
        )

        assert result.quality.status.value == "complete"
        assert not any(
            image.original_url == image_url and image.should_archive
            for image in result.images
        )
        assert result.extraction.parser_version == "nyt-parser/0.8.158"


