def test_nyt_parser_converts_legacy_dash_paragraphs_to_dividers():
    html = """
    <html><head>
      <meta property="og:title" content="Notorious Prison Escapes">
      <meta property="article:published_time" content="2015-07-14T00:00:00Z">
    </head><body><article>
      <p>The first historical escape happened at the Tower of London.</p>
      <p>———————-</p>
      <p>The next historical escape happened from the Leads Prison.</p>
      <p>————————</p>
      <p>A final account describes the escape from Alcatraz Island.</p>
    </article></body></html>
    """

    result = parse_article(
        html.encode(),
        publisher="nyt",
        canonical_url=(
            "https://www.nytimes.com/2015/07/14/world/europe/"
            "notorious-prison-escapes-in-history.html"
        ),
    )

    assert "Tower of London" in result.plain_text
    assert "Leads Prison" in result.plain_text
    assert "Alcatraz Island" in result.plain_text
    assert "——" not in result.plain_text
    assert [block.type.value for block in result.blocks].count("divider") == 2
    assert result.extraction.parser_version == "nyt-parser/0.8.158"


