def test_scmp_parser_merges_original_og_and_body_image_renditions():
    original = (
        "https://cdn.i-scmp.com/sites/default/files/d8/images/canvas/"
        "2023/11/22/editorial-photo.jpg"
    )
    og_image = (
        "https://cdn.i-scmp.com/sites/default/files/styles/og_scmp_120/"
        "public/d8/images/canvas/2023/11/22/editorial-photo.jpg?itok=og"
    )
    body_image = (
        "https://img.i-scmp.com/cdn-cgi/image/fit=contain,width=772,"
        "format=auto/sites/default/files/styles/768x768/public/d8/images/"
        "canvas/2023/11/22/editorial-photo.jpg?itok=body"
    )
    result = parse_article(
        f"""
        <html><head>
          <meta property="og:title" content="Ocean governance talks">
          <meta property="og:image" content="{og_image}">
          <script type="application/ld+json">{{
            "@type": "NewsArticle", "headline": "Ocean governance talks",
            "image": ["{original}"]
          }}</script>
        </head><body><article>
          <p>Officials discussed maritime cooperation and the shared work
          needed to protect marine resources across the region.</p>
          <figure><img src="{body_image}">
            <figcaption>Delegates met to discuss ocean governance.</figcaption>
          </figure>
          <p>Researchers said joint assessments and exchanges would help
          countries manage fisheries while avoiding unnecessary disputes.</p>
        </article></body></html>
        """.encode(),
        publisher="scmp",
        canonical_url=(
            "https://www.scmp.com/news/china/diplomacy/article/3242430/"
            "ocean-governance-talks"
        ),
    )

    assert len(result.images) == 1
    assert result.quality.images_selected == 1
    assert result.images[0].original_url == original
    assert result.images[0].candidate_urls == [original, og_image, body_image]
    assert result.images[0].caption == (
        "Delegates met to discuss ocean governance."
    )
    image_blocks = [
        block for block in result.blocks if block.type == BlockType.IMAGE
    ]
    assert len(image_blocks) == 1
    assert image_blocks[0].asset_id == result.images[0].asset_id
    assert result.extraction.parser_version == "scmp-parser/0.1.53"


