def test_scmp_apollo_parser_keeps_only_the_canonical_article_body():
    current_body = {
        "json": [
            {
                "type": "p",
                "children": [
                    {
                        "type": "text",
                        "data": "The canonical report begins with the verified event and its immediate context.",
                    }
                ],
            },
            {
                "type": "h3",
                "children": [
                    {
                        "type": "a",
                        "attribs": {
                            "href": "https://www.scmp.com/comment/article/3043901/unrelated-report"
                        },
                        "children": [
                            {
                                "type": "text",
                                "data": "An inline related-story headline",
                            }
                        ],
                    }
                ],
            },
            {
                "type": "p",
                "children": [
                    {
                        "type": "text",
                        "data": "A second paragraph records the response from officials and completes the report.",
                    }
                ],
            },
        ]
    }
    related_body = {
        "json": [
            {
                "type": "p",
                "children": [
                    {
                        "type": "text",
                        "data": "This unrelated recommended story must not be appended to the canonical report.",
                    }
                ],
            },
            {
                "type": "p",
                "children": [{"type": "text", "data": "Read more:"}],
            },
        ]
    }
    state = {
        "contentService": {
            "current": {
                "urlAlias": "/news/article/3047320/canonical-report",
                "body({})": current_body,
            },
            "related": {
                "urlAlias": "/comment/article/3043901/unrelated-report",
                "body({})": related_body,
            },
        }
    }
    result = parse_article(
        (
            '<html><head><link rel="canonical" '
            'href="https://www.scmp.com/news/article/3047320/canonical-report">'
            '<meta property="og:title" content="Canonical report">'
            '<meta property="article:published_time" content="2020-01-23T08:00:00Z">'
            '</head><body><script>window.__APOLLO_STATE__='
            + json.dumps(state, separators=(",", ":"))
            + ";</script></body></html>"
        ).encode(),
        publisher="scmp",
        canonical_url="https://www.scmp.com/news/article/3047320/canonical-report",
    )

    assert result.quality.status == ArticleStatus.COMPLETE
    assert "canonical report begins" in result.plain_text
    assert "response from officials" in result.plain_text
    assert "unrelated recommended story" not in result.plain_text
    assert "inline related-story headline" not in result.plain_text
    assert "Read more" not in result.plain_text


def test_scmp_parser_recovers_and_deduplicates_direct_apollo_body():
    image_url = "https://cdn.i-scmp.com/sites/default/files/styles/1920x1080/noodles.jpg"
    body = {
        "type": "json",
        "json": [
            {
                "type": "p",
                "children": [
                    {
                        "type": "text",
                        "data": "The noodle guide explains the regional styles and their histories.",
                    }
                ],
            },
            {
                "type": "p",
                "children": [
                    {
                        "type": "text",
                        "data": "Its second paragraph provides enough original reporting detail for a complete article.",
                    }
                ],
            },
        ],
    }
    namespace = {
        "article": {
            "__typename": "Article",
            "body": body,
            "images": [{"id": "article.images.0"}],
        },
        "article.images.0": {
            "title": "Noodles",
            'styles({"filter":{}})': [{"id": image_url}],
        },
        image_url: {"url": image_url},
    }
    apollo_state = json.dumps(
        {"cs": namespace, "defaultClient": namespace},
        separators=(",", ":"),
    )
    result = parse_article(
        (
            '<html><head><meta property="og:title" content="Asian noodle styles">'
            '<meta property="article:published_time" content="2020-04-16T08:00:00+08:00">'
            '</head><body><main><article></article></main><script>'
            "window.__APOLLO_STATE__="
            + apollo_state
            + ";</script></body></html>"
        ).encode(),
        publisher="scmp",
        canonical_url=(
            "https://www.scmp.com/cooking/article/3080344/"
            "top-asian-noodle-styles-explained"
        ),
    )

    assert result.quality.status == ArticleStatus.COMPLETE
    assert result.plain_text.count("The noodle guide explains") == 1
    assert result.plain_text.count("Its second paragraph") == 1
    assert [image.original_url for image in result.images] == [image_url]
    assert result.extraction.parser_version == "scmp-parser/0.1.53"


