@pytest.mark.parametrize(
    "marker_html",
    (
        "<h2>You might also like:</h2>",
        "<p><span>You might also like:</span></p>",
    ),
)
def test_scmp_parser_drops_young_post_you_might_also_like_tail(marker_html: str):
    html = f"""
      <html><head>
        <meta property="og:title" content="Young Post film report">
        <meta property="article:published_time" content="2019-06-02T05:50:55Z">
      </head><body>
        <div class="ArticleContent__StyledBody-sc-example">
          <p>The reporter explains how the production used practical sets and
             real vehicles to make the final action sequence convincing.</p>
          <h4>Edited by Charlotte Ames-Ettridge</h4>
          {marker_html}
          <p><a href="https://www.scmp.com/entertainment/article/1">
            An unrelated superhero recommendation
          </a></p>
          <div><p><a href="https://www.scmp.com/television/article/2">
            Another unrelated recommendation
          </a></p></div>
        </div>
      </body></html>
    """.encode()

    result = parse_article(
        html,
        publisher="scmp",
        canonical_url=(
            "https://www.scmp.com/yp/discover/entertainment/movies/article/"
            "3054658/young-post-film-report"
        ),
    )

    assert "practical sets" in result.plain_text
    assert "Edited by Charlotte Ames-Ettridge" in result.plain_text
    assert "You might also like" not in result.plain_text
    assert "unrelated recommendation" not in result.plain_text
    assert "/entertainment/article/1" not in result.body_html


