def test_zaobao_parser_does_not_promote_default_share_art_to_gallery():
    article_body = (
        "（19时－21时30分，经禧民众俱乐部，安东尼路（Anthony Rd，免费））"
        "经禧民众俱乐部主办。"
    )
    payload = json.dumps(
        {
            "@context": "https://schema.org/",
            "@type": "NewsArticle",
            "headline": "今日触点",
            "datePublished": "2016-10-10T03:30:03+08:00",
            "articleBody": article_body,
            "wordCount": 50,
            "accessMode": "visual",
            "image": {
                "@type": "ImageObject",
                "url": (
                    "https://www.zaobao.com.sg/sites/all/themes/zb2016/"
                    "assets/imgs/zbsg/zaobaosg-facebook-share.png"
                ),
            },
        },
        ensure_ascii=False,
    )
    html = f"""
    <html><head>
      <script type="application/ld+json">{payload}</script>
      <meta property="og:title" content="今日触点">
      <meta property="og:image" content="https://www.zaobao.com.sg/sites/all/themes/zb2016/assets/imgs/zbsg/default-image.png">
    </head><body><article>
      <div class="article-content-container">
        <p>（19时－21时30分，经禧民众俱乐部，安东尼路（Anthony Rd，免费））</p>
        <p>经禧民众俱乐部主办。
          <span class="paywall-message">
            请订阅或登录，以继续阅读全文！什么是早报订户新闻？
          </span>
        </p>
      </div>
    </article></body></html>
    """.encode("utf-8")

    result = parse_article(
        html,
        publisher="zaobao",
        canonical_url=(
            "https://www.zaobao.com.sg/social/events/"
            "story20161010-676168"
        ),
    )

    assert result.content_type.value == "article"
    assert result.quality.status == ArticleStatus.COMPLETE
    assert result.quality.images_selected == 0
    assert "经禧民众俱乐部主办" in result.plain_text
    assert "请订阅" not in result.plain_text
    assert "继续阅读全文" not in result.plain_text
    assert result.extraction.parser_version == "zaobao-parser/0.1.22"


