def test_zaobao_visual_opinion_prefers_complete_structured_body_over_noisy_wrapper():
    payload = json.dumps(
        {
            "@context": "https://schema.org/",
            "@type": "NewsArticle",
            "headline": "都市一角",
            "articleBody": (
                "乌云来了，黑压压地笼罩城市，令人窒息。"
                "慑人的压迫感让街道顿时失去光彩。"
                "但体积小小的鸟儿，却无惧霸气的乌云，坚持挥动双翼逆风而上，"
                "终冲破风雨，迎向蓝天。人只要努力不懈，也定能冲破逆境，展翅高飞。"
                "（文／林淑芳 摄影／何家俊）"
            ),
            "wordCount": 130,
            "accessMode": "visual",
            "image": {
                "@type": "ImageObject",
                "url": "https://static.zaobao.com.sg/s3fs-public/photo.jpg",
                "width": 800,
                "height": 443,
            },
        },
        ensure_ascii=False,
    )
    result = parse_article(
        f"""
        <html><head>
          <meta property="og:title" content="都市一角">
          <script type="application/ld+json">{payload}</script>
        </head><body><article id="MainCourse">
          <header>联合早报首页 新加坡 中国 国际 财经 体育 娱乐 生活 观点</header>
          <nav>热门新闻 最新消息 即时报道 订阅 登录 分享 收藏 推荐阅读</nav>
          <div class="media-holder main"><picture>
            <source data-srcset="https://static.zaobao.com.sg/s3fs-public/photo.jpg">
          </picture></div>
          <div class="article-content-container" id="FineDining">
            <p>乌云来了，黑压压地笼罩城市，令人窒息。</p>
            <p>慑人的压迫感让街道顿时失去光彩。</p>
          </div>
          <footer>更多新闻 关于我们 联系我们 广告服务 隐私政策 使用条款</footer>
        </article></body></html>
        """.encode("utf-8"),
        publisher="zaobao",
        canonical_url=(
            "https://www.zaobao.com.sg/forum/views/opinion/"
            "story20180121-828788"
        ),
    )

    assert result.content_type == ContentType.OPINION
    assert result.quality.status == ArticleStatus.COMPLETE
    assert "展翅高飞" in result.plain_text
    assert "文／林淑芳 摄影／何家俊" in result.plain_text
    assert "热门新闻" not in result.plain_text
    assert result.quality.images_selected >= 1
    assert result.extraction.parser_version == "zaobao-parser/0.1.22"


